const BROWSER_CHECKBOX = 'browser-check';

function openMenu({ text, translation, timestamp, sourceUrl }) {
  const menu = createMenu();

  const textInput = document.querySelector('#text-input');
  const translationInput = document.querySelector('#translation-input');

  if (!textInput || !translationInput) {
    return;
  }

  textInput.value = text;
  translationInput.value = translation;

  menu.dataset.timestamp = timestamp ?? '';
  menu.dataset.sourceUrl = sourceUrl ?? '';

  menu.classList.add('visible');
}

function createMenu() {
  const existedMenu = document.querySelector('#double-subtitles-menu');

  if (existedMenu) {
    return existedMenu;
  }

  const menu = document.createElement('div');
  const btnGroup = document.createElement('div');

  menu.classList.add('double-subtitles-menu');
  menu.setAttribute('id', 'double-subtitles-menu');

  menu.appendChild(createInput('text-input'));
  menu.appendChild(createInput('translation-input'));

  menu.appendChild(createServiceCheckbox(BROWSER_CHECKBOX, BROWSER_SVG, t('browser')));

  btnGroup.classList.add('btnGroup');
  btnGroup.appendChild(createCancelButton());
  btnGroup.appendChild(createSaveButton());

  menu.appendChild(btnGroup);

  document.body.appendChild(menu);

  return menu;
}

function createCancelButton() {
  const cancelButton = document.createElement('button');

  cancelButton.classList.add('cancelButton');
  cancelButton.textContent = t('cancel');

  cancelButton.addEventListener('click', () => {
    const menu = document.querySelector('#double-subtitles-menu');
    menu.classList.remove('visible');
  });

  return cancelButton;
}

function createSaveButton() {
  const saveButton = document.createElement('button');

  saveButton.classList.add('saveButton');
  saveButton.textContent = t('save');

  saveButton.addEventListener('click', () => {
    const menu = document.querySelector('#double-subtitles-menu');
    const textInput = document.querySelector('#text-input');
    const translationInput = document.querySelector('#translation-input');

    const timestamp = menu.dataset.timestamp ? parseFloat(menu.dataset.timestamp) : null;
    const sourceUrl = menu.dataset.sourceUrl || null;

    saveCards({
      text: textInput.value,
      translation: translationInput.value,
      timestamp,
      sourceUrl,
    });

    menu.classList.remove('visible');
  });

  return saveButton;
}

function createInput(name) {
  const input = document.createElement('textarea');

  input.classList.add('serviceInput');

  input.setAttribute('id', name);
  input.setAttribute('name', name);
  input.setAttribute('type', 'text');

  return input;
}

function createServiceCheckbox(id, svg, name) {
  const saveButton = document.createElement('label');
  saveButton.classList.add('serviceCheckbox');

  const checkbox = document.createElement('input');
  checkbox.classList.add('saveCheckbox');
  checkbox.type = 'checkbox';
  checkbox.value = id;
  checkbox.checked = true;
  saveButton.appendChild(checkbox);

  // `svg` is a static string constant defined in this extension, not external
  // input, so it is the only part parsed as markup. Parsing happens in a detached
  // holder and only the <svg> element is moved over, keeping the same DOM shape
  // the stylesheet expects.
  const holder = document.createElement('div');
  holder.innerHTML = svg;

  if (holder.firstElementChild) {
    saveButton.appendChild(holder.firstElementChild);
  }

  const label = document.createElement('span');
  label.textContent = name;
  saveButton.appendChild(label);

  return saveButton;
}

function saveCards({ text, translation, timestamp, sourceUrl }) {
  const menu = document.querySelector('#double-subtitles-menu');
  const checkboxes = menu ? menu.querySelectorAll('.saveCheckbox') : [];
  const mapCheckBoxToService = {
    [BROWSER_CHECKBOX]: () => {
      saveToSyncStorage({ text, translation, timestamp, sourceUrl }, showSaveToast);
    },
  };

  Array.from(checkboxes).forEach(checkbox => {
    if (checkbox.checked) {
      mapCheckBoxToService[checkbox.value]?.();
    }
  });
}

function showSaveToast(succeeded = true) {
  const existing = document.querySelector('.save-toast');
  if (existing) {
    existing.remove();
  }

  const toast = document.createElement('div');
  toast.classList.add('save-toast');
  if (!succeeded) {
    toast.classList.add('save-toast--error');
  }
  toast.textContent = succeeded ? t('saved') : t('saveFailed');
  document.body.appendChild(toast);

  requestAnimationFrame(() => {
    toast.classList.add('save-toast--visible');
  });

  setTimeout(() => {
    toast.classList.remove('save-toast--visible');
    toast.addEventListener('transitionend', () => toast.remove(), { once: true });
  }, 2000);
}
